cat > /tmp/free_com4.ps1 << 'EOF'
$ErrorActionPreference = 'Continue'
Write-Host '=== handle/open test ==='
try {
  $s = New-Object System.IO.Ports.SerialPort('COM4', 115200)
  $s.Open()
  Write-Host 'COM4 was free; opened OK, closing'
  $s.Close(); $s.Dispose()
} catch {
  Write-Host ("COM4 busy: " + $_.Exception.Message)
}

Write-Host '=== processes mentioning COM4 ==='
Get-CimInstance Win32_Process | Where-Object {
  $_.CommandLine -and ($_.CommandLine -match 'COM4')
} | ForEach-Object {
  '{0} pid={1} {2}' -f $_.Name, $_.ProcessId, $_.CommandLine
}

Write-Host '=== serial-ish processes ==='
$names = @('SSCOM32','SSCOM64','sscom','putty','kitty','SecureCRT','TeraTerm','mtty','MThings','MThingsStudio','Serial Port Utility','UARTAssist','XCOM','com0com','hwinfo','openocd','STM32CubeProgrammer','ST-LINK_GUI')
Get-Process -ErrorAction SilentlyContinue | Where-Object {
  $n = $_.ProcessName
  $names | Where-Object { $n -like "*$_*" } | Select-Object -First 1
} | ForEach-Object {
  $cl = ''
  try { $cl = (Get-CimInstance Win32_Process -Filter ("ProcessId=" + $_.Id)).CommandLine } catch {}
  '{0} pid={1} {2}' -f $_.ProcessName, $_.Id, $cl
}

Write-Host '=== powershell holding SerialPort scripts ==='
Get-CimInstance Win32_Process | Where-Object {
  $_.Name -match 'powershell|pwsh|python' -and $_.CommandLine -and (
    $_.CommandLine -match 'SerialPort|stage0_accept|stage1_|serial_|COM4|COM3|COM6'
  )
} | ForEach-Object {
  '{0} pid={1} {2}' -f $_.Name, $_.ProcessId, $_.CommandLine
}
EOF
powershell.exe -NoProfile -ExecutionPolicy Bypass -File /tmp/free_com4.ps1

cat > /tmp/free_com4b.ps1 << 'EOF'
$ErrorActionPreference = 'Continue'
# List COM devices
Write-Host '=== COM ports ==='
Get-CimInstance Win32_SerialPort | Select-Object DeviceID, Name, Description, PNPDeviceID | Format-List
[System.IO.Ports.SerialPort]::GetPortNames() | ForEach-Object { "port: $_" }

# Try handle-like: open files via Get-Process modules won't help for COM
# Kill common holders if user wants COM4 free - first identify more carefully
Write-Host '=== all MThings / serial utility ==='
Get-CimInstance Win32_Process | Where-Object {
  $_.Name -match 'MThings|sscom|SSCOM|putty|kitty|mtty|UART|XCOM|ComAssistant|SerialMonitor|cursor|Code' -or
  ($_.CommandLine -and $_.CommandLine -match 'SerialPort|COM[0-9]')
} | ForEach-Object {
  '{0} pid={1}' -f $_.Name, $_.ProcessId
  if ($_.CommandLine) { '  ' + $_.CommandLine.Substring(0, [Math]::Min(200, $_.CommandLine.Length)) }
}

# Check if handle.exe exists
$handle = @(
  'C:\Sysinternals\handle.exe',
  'C:\Tools\handle.exe',
  "$env:USERPROFILE\Downloads\handle.exe",
  'handle.exe'
) | Where-Object { Get-Command $_ -ErrorAction SilentlyContinue } | Select-Object -First 1
if (-not $handle) {
  foreach ($c in @('C:\Sysinternals\handle.exe','C:\Tools\Sysinternals\handle.exe')) {
    if (Test-Path $c) { $handle = $c; break }
  }
}
if ($handle) {
  Write-Host "=== handle COM4 via $handle ==="
  & $handle -accepteula -nobanner COM4 2>&1
} else {
  Write-Host 'handle.exe not found'
}
EOF
