cat > /mnt/c/Users/19y/AppData/Local/Temp/close_mthings.ps1 << 'EOF'
$ErrorActionPreference = 'Continue'
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class Win32Close {
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
  [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  public const uint WM_CLOSE = 0x0010;
}
"@

$targetPid = 26372
$hwnds = New-Object System.Collections.Generic.List[IntPtr]
[Win32Close]::EnumWindows({
  param($h,$l)
  $pidOut = 0
  [void][Win32Close]::GetWindowThreadProcessId($h, [ref]$pidOut)
  if ($pidOut -eq $targetPid -and [Win32Close]::IsWindowVisible($h)) {
    $script:hwnds.Add($h) | Out-Null
  }
  return $true
}, [IntPtr]::Zero)

Write-Host ("visible hwnd count=" + $hwnds.Count)
foreach ($h in $hwnds) {
  Write-Host ("PostMessage WM_CLOSE hwnd=" + $h)
  [void][Win32Close]::PostMessage($h, [Win32Close]::WM_CLOSE, [IntPtr]::Zero, [IntPtr]::Zero)
}

# Also try Stop-Process again
Start-Sleep -Seconds 2
if (Get-Process -Id $targetPid -ErrorAction SilentlyContinue) {
  Write-Host 'still alive, try Stop-Process'
  Stop-Process -Id $targetPid -Force -ErrorAction SilentlyContinue
  Start-Sleep -Seconds 1
}

if (Get-Process -Name MThings -ErrorAction SilentlyContinue) {
  Write-Host 'MThings STILL RUNNING'
} else {
  Write-Host 'MThings closed'
}

try {
  $s = New-Object System.IO.Ports.SerialPort('COM4', 9600)
  $s.Open(); Write-Host 'PASS: COM4 free'; $s.Close(); $s.Dispose()
} catch { Write-Host ("FAIL: " + $_.Exception.Message) }

